#include <vector>
#include <algorithm>

int shortest_span(const std::vector<int>& values, long long threshold) {
    int n = values.size();
    std::vector<long long> prefix_sum(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        prefix_sum[i + 1] = prefix_sum[i] + values[i];
    }

    int min_length = n + 1;
    for (int i = 0; i < n; ++i) {
        for (int j = i; j < n; ++j) {
            if (prefix_sum[j + 1] - prefix_sum[i] >= threshold) {
                min_length = std::min(min_length, j - i + 1);
            }
        }
    }

    return min_length == n + 1 ? 0 : min_length;
}
