#include <vector>
#include <string>
#include <algorithm>
#include <unordered_map>
#include <cassert>

std::vector<std::string> top_words(const std::vector<std::string>& words, int k) {
    if (k <= 0) return {};

    std::unordered_map<std::string, int> word_count;
    for (const auto& word : words) {
        ++word_count[word];
    }

    std::vector<std::pair<std::string, int>> sorted_words(word_count.begin(), word_count.end());
    std::sort(sorted_words.begin(), sorted_words.end(), [](const auto& a, const auto& b) {
        return a.second == b.second ? a.first < b.first : a.second > b.second;
    });

    std::vector<std::string> result;
    for (int i = 0; i < std::min(k, static_cast<int>(sorted_words.size())); ++i) {
        result.push_back(sorted_words[i].first);
    }

    return result;
}

// Test cases
int main() {
    assert(top_words({}, 3) == std::vector<std::string>());
    assert(top_words({"apple", "banana", "apple", "orange", "banana"}, 2) == std::vector<std::string>{"banana", "apple"});
    assert(top_words({"hello", "world", "hello", "cpp"}, 1) == std::vector<std::string>{"hello"});
    assert(top_words({"cpp", "is", "fun", "cpp"}, 3) == std::vector<std::string>{"cpp", "fun", "is"});
    assert(top_words({"fun", "is", "cpp", "fun"}, 2) == std::vector<std::string>{"fun", "is"});
    assert(top_words({"fun", "is", "cpp", "fun"}, 0) == std::vector<std::string>());

    return 0;
}
