int main() {
    std::unordered_map<std::string, int> inventory;
    std::string command;

    while (std::getline(std::cin, command)) {
        if (command == "PUT name") {
            std::string name;
            std::cin >> name;
            inventory[name]++;
        } else if (command == "TAKE name") {
            std::string name;
            std::cin >> name;
            if (inventory[name] > 0) {
                inventory[name]--;
            }
        } else if (command == "QUERY name") {
            std::string name;
            std::cin >> name;
            if (inventory.count(name) > 0) {
                std::cout << inventory[name] << std::endl;
            } else {
                std::cout << "0" << std::endl;
            }
        }
    }

    return 0;
}
